diff --git a/deploy/nginx.conf b/deploy/nginx.conf
index a61b17f..f7df20b 100644
--- a/deploy/nginx.conf
+++ b/deploy/nginx.conf
@@ -162,6 +162,51 @@ http {
             # 不覆盖上游 Content-Type；后端应返回 text/event-stream。
         }

+        # 运行事件续流 SSE 端点（GET + text/event-stream）。
+        # run_id 是 UUID，不能用 = 做精确匹配，因此这里使用正则 location。
+        # 未加 ^~ 的 /api/ 前缀 location 优先级低于正则 location，所以本段
+        # 的长连接参数会覆盖 /api/ 的默认缓冲与 60s 读超时。
+        # 注意：不要给 /api/ 加 ^~，否则正则 location 将不再优先。
+        location ~ ^/api/v1/runs/[0-9a-fA-F-]+/stream$ {
+            proxy_pass http://agent-hub-backend;
+
+            # 使用 HTTP/1.1 与后端通信。HTTP/1.0 默认短连接、无 chunked，
+            # 不适合长时间流式响应。
+            proxy_http_version 1.1;
+
+            proxy_set_header Host $host;
+            proxy_set_header X-Real-IP $remote_addr;
+            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
+            proxy_set_header X-Forwarded-Proto $scheme;
+            proxy_set_header X-Request-ID $request_id;
+
+            # 清除逐跳的 Connection 头（配合 HTTP/1.1 与 upstream keepalive），
+            # 避免把 "Connection: close" 传给后端。
+            proxy_set_header Connection "";
+
+            # 关闭响应缓冲：后端每产生一个 SSE 事件就立即转发给浏览器，
+            # 不攒满 proxy_buffer、也不等响应结束；这是逐帧流式输出的关键。
+            proxy_buffering off;
+
+            # 禁止缓存流式响应，避免中间层缓存半截事件或复用旧流。
+            proxy_cache off;
+
+            # 关闭 gzip：压缩器会引入额外缓冲，破坏事件到达的实时性。
+            gzip off;
+
+            # 续流可能长时间空闲（仅靠 15s ping 注释帧保活）；读超时放宽到
+            # 1 小时，默认 60s 会误判上游超时并返回 504、中断续流。
+            proxy_read_timeout 3600s;
+
+            # 写超时同样放宽：客户端网络慢时，给 nginx 足够时间写完事件。
+            proxy_send_timeout 3600s;
+
+            # 连接建立超时保持较短，后端不可用时快速失败。
+            proxy_connect_timeout 10s;
+
+            # 不覆盖上游 Content-Type；后端应返回 text/event-stream。
+        }
+
         # 健康检查透传：供负载均衡/编排探活，不经过 SPA fallback。
         location = /healthz {
             proxy_pass http://agent-hub-backend/healthz;

